    \end{array}
\right]}
= \boxed{\left[
    \begin{array}{cc}
        0 & 0\\
        0 & 1
    \end{array}
\right]}
\end{equation*}

\begin{equation*}
P = (v \cdot W^\intercal ) \left( [v \cdot v^\intercal , v] [v \cdot v^\intercal , v]^\intercal \right)^{-1} [v \cdot v^\intercal , v] \\
= \left( \left[
    \begin{array}{cc}
        0 & 1\\
        y & w \cdot v
    \end{array}
\right] \left[
    \begin{array}{cc}
        0 & 0\\
        0 & 1
    \end{array}
\right] \right)
\left( \left[
